fn is_sorted(arr: &Vec[Int]) -> Bool {
  for i in 0..arr.len()-1 {
    if arr[i] > arr[i+1] { return false; }
  }
  return true;
}

fn binary_search(arr: &Vec[Int], target: Int) -> Option[Int]
  requires: is_sorted(arr);
  ensures: match result {
    Some(idx) => idx < arr.len() && arr[idx] == target,
    None => true,
  };
{
  var lo = 0;
  var hi = arr.len();
  while lo < hi {
    let mid = (lo + hi) / 2;
    if arr[mid] == target { return Some(mid); }
    if arr[mid] < target { lo = mid + 1; }
    else { hi = mid; }
  }
  return None();
}

fn main() -> Int {
  let v = Vec[Int]();
  v.push(1); v.push(3); v.push(5); v.push(7);
  match binary_search(&v, 5) {
    Some(idx) => return idx,
    None => return 0,
  }
}
